/* PDF del preventivo (layout moderno, stessi contenuti del «Documento Master per Conto Formazione» di Ask Consulting).
   Si crea nel browser con jsPDF (file jspdf.umd.min.js accanto a questo). I numeri arrivano già calcolati dal riepilogo
   (pvCalcola di app.js), così PDF, Excel e riepilogo coincidono.
   Sorgente: strumenti/pdf/pdf-preventivo.src.js → «node strumenti/pdf/crea.js» scrive public/pdf-preventivo.js con il logo dentro. */
"use strict";
(function(){
const LOGO="data:image/png;base64,", LOGO_W=738, LOGO_H=333;
let jspdfPronto=null;
function caricaJsPDF(){return jspdfPronto||(jspdfPronto=new Promise((ok,ko)=>{
  if(window.jspdf)return ok(window.jspdf);
  const sc=document.createElement("script");sc.src="jspdf.umd.min.js";
  sc.onload=()=>ok(window.jspdf);sc.onerror=()=>{jspdfPronto=null;ko(new Error("Non riesco a caricare il generatore di PDF."))};
  document.head.appendChild(sc)}))}

const eu=v=>{v=Math.round((Number(v)||0)*100)/100;const s=Math.abs(v).toFixed(2).split("."),i=s[0].replace(/\B(?=(\d{3})+(?!\d))/g,".");return (v<0?"-":"")+i+","+s[1]+" €"};
const dIt=s=>/^\d{4}-\d{2}-\d{2}$/.test(s||"")?s.split("-").reverse().join("/"):(s||"");
const numIt=v=>String(Math.round((Number(v)||0)*100)/100).replace(".",",");

// colori presi dal logo
const BLU=[19,82,160], BLU_SCURO=[14,47,92], ARANCIO=[238,125,59], INK=[28,32,40], GRIGIO=[107,114,128], LINEA=[222,226,233], FONDO=[243,246,250];
const PW=595.28, PH=841.89, M=42, W=PW-2*M, FONDO_PAG=772;

async function crea(p,c){
  const {jsPDF}=await caricaJsPDF();
  const num=v=>{let s=String(v==null?"":v).trim().replace(/[\s€]/g,"");if(s.indexOf(",")>=0)s=s.replace(/\./g,"").replace(",",".");const x=Number(s);return isFinite(x)?x:0};
  const doc=new jsPDF({unit:"pt",format:"a4"});
  doc.setProperties({title:"Preventivo "+nomeAz(p),author:"Ask Consulting S.r.l.",creator:"Preventivi Ask"});
  const font=(stile,size,col)=>{doc.setFont("helvetica",stile||"normal");doc.setFontSize(size||9);doc.setTextColor(...(col||INK))};
  const T=(t,x,y,o)=>{if(t==null||t==="")return;doc.text(String(t),x,y,Object.assign({baseline:"alphabetic"},o||{}))};
  const spaziato=(t,x,y,sp,o)=>{sp=sp||0.6;o=o||{};if(o.align==="right"){x-=doc.getTextWidth(String(t))+sp*(String(t).length-1);o=Object.assign({},o,{align:"left"})}
    doc.setCharSpace(sp);T(t,x,y,o);doc.setCharSpace(0)};
  const linea=(x1,y1,x2,y2,col,w)=>{doc.setDrawColor(...(col||LINEA));doc.setLineWidth(w||0.6);doc.line(x1,y1,x2,y2)};
  const righe=(t,w)=>t?doc.splitTextToSize(String(t),w):[];
  let y=0;

  /* ---- intestazione ---- */
  const lw=118,lh=lw*LOGO_H/LOGO_W;
  try{doc.addImage(LOGO,"PNG",M,34,lw,lh,undefined,"FAST")}catch(e){}
  font("bold",7.5,ARANCIO);spaziato("PREVENTIVO",PW-M,46,1.2,{align:"right"});
  font("bold",17,BLU_SCURO);T("Piano formativo finanziato",PW-M,66,{align:"right"});
  font("normal",9,GRIGIO);T("Fondimpresa · Conto Formazione aziendale",PW-M,80,{align:"right"});
  y=34+lh+16;
  linea(M,y+1.1,PW-M,y+1.1);
  y+=26;

  /* ---- azienda e dati del preventivo ---- */
  const colDx=PW-M-180;
  font("bold",7,GRIGIO);spaziato("AZIENDA",M,y,1);
  font("bold",15,INK);const nl=righe(nomeAz(p),colDx-M-20);
  nl.slice(0,3).forEach((l,k)=>T(l,M,y+18+k*17));
  let yAz=y+18+(Math.min(nl.length,3)-1)*17;
  const cf=(p.aziende||[]).map(a=>a.cf).filter(Boolean);
  if(cf.length){font("normal",8.5,GRIGIO);yAz+=14;T("C.F. "+cf.join(" · "),M,yAz)}
  const meta=[["Data",dIt(p.dataPreventivo)],["Periodo di effettuazione del piano",p.periodo||""]].filter(x=>x[1]);
  let ym=y;meta.forEach(([k,v])=>{font("bold",7,GRIGIO);spaziato(k.toUpperCase(),colDx,ym,1);font("normal",9.5,INK);
    const vl=righe(v,150);vl.slice(0,2).forEach((l,i)=>T(l,colDx,ym+13+i*11));ym+=13+(Math.min(vl.length,2)-1)*11+14});
  y=Math.max(yAz,ym-14)+24;

  /* ---- riquadro con i numeri principali ---- */
  // il recupero spese va nella tabella di progettazione: la docenza lo esclude
  const recup=Number(c.recupero)>0?Number(c.recupero):0, docCorsi=Math.round((Number(c.docenza)-recup)*100)/100;
  const kh=60;doc.setFillColor(...FONDO);doc.roundedRect(M,y,W,kh,6,6,"F");
  doc.setFillColor(...BLU);doc.roundedRect(M,y,4,kh,2,2,"F");
  const kpi=[["Totale piano formativo",eu(c.totale),BLU],["Docenza finanziata",eu(docCorsi),INK],["Ore di formazione",numIt(c.ore),INK]];
  const kw=W/3;
  kpi.forEach(([lab,val,col],i)=>{const x=M+18+i*kw;if(i)linea(M+i*kw,y+12,M+i*kw,y+kh-12);
    font("bold",7,GRIGIO);spaziato(lab.toUpperCase(),x,y+22,0.8);font("bold",i?14:17,col);T(val,x,y+44)});
  y+=kh+30;

  /* ---- tabelle ---- */
  const nuovaPagina=()=>{doc.addPage();y=50};
  const titolo=(t,sub)=>{if(y+70>FONDO_PAG)nuovaPagina();font("bold",11.5,BLU_SCURO);T(t,M,y);if(sub){const w=doc.getTextWidth(t);font("normal",8.5,GRIGIO);T(sub,M+w+8,y)}y+=12};
  // colonne della docenza
  const C=[{k:"doc",t:"Docente / fornitore",w:104},{k:"att",t:"Tematica formativa",w:170},{k:"per",t:"Periodo",w:76},{k:"lav",t:"N. min. lav.",w:58,a:"c"},{k:"ore",t:"Ore",w:36,a:"c"},{k:"imp",t:"Importo",w:67,a:"r"}];
  let cx=M;C.forEach(k=>{k.x=cx;cx+=k.w});
  const xA=(k,a)=>a==="r"?k.x+k.w-6:a==="c"?k.x+k.w/2:k.x+6;
  const intest=cols=>{font("bold",6.8,GRIGIO);cols.forEach(k=>{doc.setCharSpace(0.5);T(k.t.toUpperCase(),xA(k,k.a),y+10,{align:k.a==="r"?"right":k.a==="c"?"center":"left"});doc.setCharSpace(0)});
    y+=17;linea(M,y,PW-M,y,BLU,0.9)};
  const riga=(cols,val,opz)=>{opz=opz||{};
    font(opz.stile||"normal",8.8,opz.col||INK);
    const L=cols.map(k=>k.a?[String(val[k.k]==null?"":val[k.k])]:righe(val[k.k]||"",k.w-12));
    const h=Math.max(22,Math.max(...L.map(l=>l.length))*11+11);
    if(y+h>FONDO_PAG){nuovaPagina();intest(cols)}
    if(opz.fondo){doc.setFillColor(...opz.fondo);doc.rect(M,y,W,h,"F")}
    cols.forEach((k,i)=>{font(k.k==="imp"&&!opz.stile?"bold":opz.stile||"normal",8.8,opz.col||INK);
      if(opz.colonne&&opz.colonne[k.k])doc.setTextColor(...opz.colonne[k.k]);
      L[i].forEach((l,j)=>T(l,xA(k,k.a),y+14.5+j*11,{align:k.a==="r"?"right":k.a==="c"?"center":"left"}))});
    y+=h;if(!opz.noLinea)linea(M,y,PW-M,y)};

  const corsi=(p.corsi||[]).filter(co=>co.titolo||co.docente||num(co.ore)||(!co.residuo&&num(co.importo)));
  titolo("Docenza",corsi.length===1?"1 corso":corsi.length+" corsi");
  intest(C);
  corsi.forEach(co=>{const i=(p.corsi||[]).indexOf(co);
    riga(C,{doc:co.docente||"",att:co.titolo||"",per:String(co.periodo||p.periodo||"").trim(),lav:String(co.partecipanti||"").trim(),ore:String(co.ore||"").trim(),imp:eu(c.importi[i])})});
  // totale docenza
  if(y+26>FONDO_PAG)nuovaPagina();
  doc.setFillColor(...FONDO);doc.rect(M,y,W,26,"F");
  font("bold",8.8,INK);T("Totale docenza finanziata",C[3].x-6,y+16.5,{align:"right"});
  T(numIt(c.ore)+" ore",xA(C[4],"c"),y+16.5,{align:"center"});T(eu(docCorsi),xA(C[5],"r"),y+16.5,{align:"right"});
  y+=26+30;

  const P2=[{k:"sog",t:"Soggetto",w:150},{k:"att",t:"Attività",w:W-150-90},{k:"imp",t:"Importo",w:90,a:"r"}];
  cx=M;P2.forEach(k=>{k.x=cx;cx+=k.w});
  titolo("Progettazione, gestione e rendicontazione");
  intest(P2);
  [["Ask Consulting S.r.l.","Attività preparatorie e di accompagnamento",c.askPrep],
   ["Ask Consulting S.r.l.","Attività di gestione e rendicontazione",c.askGest],
   ...(recup>0?[["Recupero spese","Spese forfettarie azienda cliente",recup]]:[]),
   ["Revisore dei conti","Attività di certificazione delle spese sostenute",c.revisore]].forEach(r=>riga(P2,{sog:r[0],att:r[1],imp:eu(r[2])}));
  y+=22;

  /* ---- totale del piano ---- */
  if(y+54>FONDO_PAG)nuovaPagina();
  doc.setFillColor(...BLU_SCURO);doc.roundedRect(M,y,W,54,6,6,"F");
  doc.setFillColor(...ARANCIO);doc.roundedRect(M,y,5,54,2.5,2.5,"F");
  font("bold",12,[255,255,255]);T("Totale piano finanziato",M+22,y+24);
  font("normal",8.5,[196,210,232]);T("Rimborso delle spese sostenute",M+22,y+38);
  font("bold",20,[255,255,255]);T(eu(c.totalePiano),PW-M-20,y+34,{align:"right"});
  y+=54+26;

  /* ---- piè di pagina su ogni pagina ---- */
  const n=doc.getNumberOfPages();
  for(let i=1;i<=n;i++){doc.setPage(i);
    linea(M,PH-56,PW-M,PH-56);
    font("bold",7.5,BLU);T("Ask Consulting S.r.l.",M,PH-42);
    font("normal",7,GRIGIO);T("Cuneo – Via Statuto, 8 · Tel. 0171 453820 · progetti@askconsulting.it",M,PH-31);
    T("C.F. e P.IVA 02923810044 · Registro Imprese di Cuneo n. 02923810044 · REA n. 247716",M,PH-21);
    T("Pagina "+i+" di "+n,PW-M,PH-42,{align:"right"})}
  return doc;
}

function nomeAz(p){return (p.aziende||[]).map(a=>a.nome).filter(Boolean).join(" + ")||"Azienda"}
// nome del file: «Preventivo AZIENDA 17-11-2026.pdf»
function nomeFile(p){return ("Preventivo "+nomeAz(p)+" "+dIt(p.dataPreventivo).replace(/\//g,"-")).replace(/[\\/:*?"<>|]+/g,"_").slice(0,150).trim()+".pdf"}

window.pdfPreventivo=async function(p,c){
  const doc=await crea(p,c), nome=nomeFile(p), blob=doc.output("blob");
  const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=nome;document.body.appendChild(a);a.click();
  setTimeout(()=>{URL.revokeObjectURL(url);a.remove()},4000);
  return nome;
};
window.pdfPreventivoBlob=async(p,c)=>(await crea(p,c)).output("blob");
})();
